INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.114.0',
  '2026-10-04',
  'Пульт ТВ: избранное — отмеченное встаёт в начало списка',
  E'У сериала, фильма и папки появилась кнопка «☆ В избранное» — там же, где и «Инфо»: на экране сериала, на экране папки и в карточке «Инфо», которой открывается фильм.\n\nОтмеченное встаёт в начало своего раздела: сериалы к сериалам, фильмы к фильмам. Остальной порядок не меняется — внутри избранного всё так же по алфавиту. На плитке в левом верхнем углу появляется звёздочка, тем же тёмным блоком с белым текстом, что и число сезонов справа.\n\nОтметки хранит агент, а не браузер приставки: это свойство медиатеки. Открыли ту же библиотеку со второй приставки или с телефона — порядок тот же. Переименование в админке отметку не сбрасывает.',
  E'favorites.go, POST /api/favorite {id, on}, список в favorites.json. Ключ записи — ПУТЬ, а не id: id это sha256 пути, и переименование в админке сбросило бы отметку; renamePath двигает её вместе с marks и frames. У папки-подборки пути нет (она живёт только в кэше агента), поэтому ключом идёт её собственный id, и при удалении папки отметка снимается.\n\nmarkFavorites проставляет флаг и поднимает отмеченное устойчивой сортировкой по одному признаку — порядок по названию внутри группы остаётся прежним. Рекурсивно заходит в items папок, поэтому звёздочки видно и внутри подборки.\n\nПосле нажатия страница перечитывает /api/catalog, а не пересортировывает список сама: своя сортировка давала тот же набор, но другой порядок ВНУТРИ избранного, и после обновления страницы плитки прыгали бы. Подпись кнопки и звёздочка обновляются сразу, до ответа каталога.\n\nПроверено в браузере: отметка у сериала, фильма (через «Инфо» из плеера) и папки, подъём в начало своего раздела без перемешивания разделов, звёздочка на плитке, снятие отметки, переживание перезагрузки страницы. Тесты favorites_test.go, включая перенос отметки при переименовании.'
);
